            customers = [i for i in range(len(demands)) if i != depot]
        else:
            customers = []

    if isinstance(demands, dict):
        def demand_of(c):
            return demands.get(c, 0)
    elif isinstance(demands, list):
        def demand_of(c):
            if 0 <= c < len(demands):
                return demands[c]
            return 0
    else:
        def demand_of(c):
            return 0

    def coord_of(c):
        if coords is None:
            return None
        if isinstance(coords, dict):
            return coords.get(c)
        if isinstance(coords, list) and 0 <= c < len(coords):
            return coords[c]
        return None

    def d(a, b):
        if dist is not None:
            if isinstance(dist, dict):
                row = dist.get(a)
                if isinstance(row, dict):
                    return row.get(b, 0)
                if isinstance(row, list) and 0 <= b < len(row):
                    return row[b]
                pair = (a, b)
                if pair in dist:
                    return dist[pair]
                return 0
            if isinstance(dist, list) and 0 <= a < len(dist) and 0 <= b < len(dist[a]):
                return dist[a][b]
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is not None and cb is not None and len(ca) >= 2 and len(cb) >= 2:
            dx = ca[0] - cb[0]
            dy = ca[1] - cb[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(a - b)

    customers = [c for c in customers if c != depot]
    customers.sort(key=lambda c: (d(depot, c), c))

    unassigned = customers[:]
    routes = []

    while unassigned:
        route = []
        load = 0
        current = depot

        best_i = None
        best_key = None
        for i, c in enumerate(unassigned):
            dem = demand_of(c)
            if capacity is not None and dem > capacity:
                continue
            key = (d(depot, c), dem, c)
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        if best_i is None:
            best_i = 0

        c = unassigned.pop(best_i)
        route.append(c)
        load += demand_of(c)
        current = c

        while True:
            best_i = None
            best_key = None
            for i, cand in enumerate(unassigned):
                dem = demand_of(cand)
                if capacity is not None and load + dem > capacity:
                    continue
                key = (d(current, cand), dem, cand)
                if best_key is None or key < best_key:
                    best_key = key
                    best_i = i
            if best_i is None:
                break
            c = unassigned.pop(best_i)
            route.append(c)
            load += demand_of(c)
            current = c

        routes.append(route)

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        total = d(depot, route[0])
        for i in range(len(route) - 1):
            total += d(route[i], route[i + 1])
        total += d(route[-1], depot)
        return total

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route
        improved = True
        while improved:
            improved = False
            base = route_cost(route)
            best_delta = 0
            best_i = None
            best_j = None
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = route[:i + 1] + route[i + 1:j + 1][::-1] + route[j + 1:]
                    delta = route_cost(cand) - base
                    if delta < best_delta - 1e-12 or (abs(delta - best_delta) <= 1e-12 and best_i is not None and (i, j) < (best_i, best_j)):
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i is not None and best_delta < -1e-12:
                route = route[:best_i + 1] + route[best_i + 1:best_j + 1][::-1] + route[best_j + 1:]
                improved = True
        return route

    routes = [two_opt(r) for r in routes]

    changed = True
    while changed:
        changed = False
        best = None
        for i, r1 in enumerate(routes):
            for pos, c in enumerate(r1):
                dem = demand_of(c)
                for j, r2 in enumerate(routes):
                    if i == j:
                        continue
                    if capacity is not None and route_load(r2) + dem > capacity:
                        continue
                    for ins in range(len(r2) + 1):
                        nr1 = r1[:pos] + r1[pos + 1:]
                        nr2 = r2[:ins] + [c] + r2[ins:]
                        delta = route_cost(nr1) + route_cost(nr2) - route_cost(r1) - route_cost(r2)
                        key = (delta, i, pos, j, ins, c)
                        if best is None or key < best[0]:
                            best = (key, i, pos, j, ins, nr1, nr2)
        if best is not None and best[0][0] < -1e-12:
            _, i, pos, j, ins, nr1, nr2 = best
            routes[i] = nr1
            routes[j] = nr2
            routes = [r for r in routes if r]
            changed = True

    routes = [two_opt(r) for r in routes]

    seen = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c not in seen:
                seen.add(c)
                nr.append(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    missing = [c for c in customers if c not in seen]
    if missing:
        missing.sort(key=lambda c: (d(depot, c), c))
        for c in missing:
            dem = demand_of(c)
            best = None
            for i, r in enumerate(routes):
                if capacity is not None and route_load(r) + dem > capacity:
                    continue
                for ins in range(len(r) + 1):
                    cand = r[:ins] + [c] + r[ins:]
                    key = (route_cost(cand), i, ins)
                    if best is None or key < best[0]:
                        best = (key, i, ins)
            if best is None:
                routes.append([c])
            else:
                _, i, ins = best
                routes[i] = routes[i][:ins] + [c] + routes[i][ins:]

    routes = [r for r in routes if r]
    return routes
